import { useState } from "react";
import CompanyLayout from "./CompanyLayout";

const WILAYAS  = ["Alger","Oran","Constantine","Annaba","Béjaïa","Tizi Ouzou","Blida","Sétif","Tlemcen","Batna"];
const TYPES    = ["on-site","remote","hybrid"]; 


const ALL_SKILLS = ["React","Vue","Angular","Node.js","Express","Django","FastAPI","Laravel","Python","Java","PHP","C++","SQL","PostgreSQL","MongoDB","Docker","Git","Linux","Flutter","TypeScript","Redis","Kubernetes","TensorFlow","Figma"];

const INIT_OFFERS = [
  {
    id:1, title:"Full-Stack Web Developer", description:"Join our digital team to build internal platforms using React and Node.js. You will work alongside senior engineers on real production systems.",
    wilaya:"Alger", internshipType:"on-site", domain:"Web Development", duration:"6 months",
    skills:["React","Node.js","PostgreSQL","Git"], isActive:true, applicants:14, posted:"Apr 18, 2025",
  },
  {
    id:2, title:"Data Analyst Intern", description:"Work with our data science team to analyze energy production data and build Power BI dashboards for executives.",
    wilaya:"Alger", internshipType:"hybrid", domain:"Data Science", duration:"4 months",
    skills:["Python","SQL","Power BI"], isActive:true, applicants:9, posted:"Apr 15, 2025",
  },
  {
    id:3, title:"DevOps Intern", description:"Help manage our CI/CD pipelines and Kubernetes clusters. Great opportunity for someone with a passion for automation and cloud infrastructure.",
    wilaya:"Alger", internshipType:"on-site", domain:"DevOps", duration:"4 months",
    skills:["Docker","Kubernetes","Linux","Git"], isActive:false, applicants:4, posted:"Apr 01, 2025",
  },
];

const EMPTY_FORM = {
  title:"", description:"", wilaya:"Alger", internshipType:"on-site",
  domain:"Web Development", duration:"6 months", skills:[], isActive:true,
};

const TYPE_BADGE = { "on-site":"badge-blue", "remote":"badge-green", "hybrid":"badge-orange" };

function OfferModal({ offer, onClose, onSave }) {
  const [form, setForm] = useState(offer ? {...offer} : {...EMPTY_FORM});
  const upd = (k,v) => setForm(f=>({...f,[k]:v}));
  const toggleSkill = s => setForm(f=>({...f, skills: f.skills.includes(s)?f.skills.filter(x=>x!==s):[...f.skills,s]}));
  const isEdit = !!offer?.id;

  const valid = form.title.trim().length > 2 && form.description.trim().length > 10;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-box" onClick={e=>e.stopPropagation()}>
        <div className="flex items-center justify-between mb-5">
          <h3 className="font-syne font-extrabold text-slate-900 text-xl">
            {isEdit ? "Edit offer" : "Post new offer"}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 text-xl transition-colors">✕</button>
        </div>

        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Job title <span className="text-red-500">*</span></label>
            <input value={form.title} onChange={e=>upd("title",e.target.value)} placeholder="e.g. Full-Stack Web Developer" className="input-field"/>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">
              Description <span className="text-red-500">*</span>
            </label>
            <textarea rows={4} value={form.description} onChange={e=>upd("description",e.target.value)}
              placeholder="Describe the role and responsibilities..." className="input-field resize-none"/>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Wilaya</label>
              <select value={form.wilaya} onChange={e=>upd("wilaya",e.target.value)} className="input-field">
                {WILAYAS.map(w=><option key={w}>{w}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Type</label>
              <select value={form.internshipType} onChange={e=>upd("internshipType",e.target.value)} className="input-field">
                {TYPES.map(t=><option key={t} value={t}>{t.charAt(0).toUpperCase()+t.slice(1)}</option>)}
              </select>
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-2">Required skills</label>
            <div className="flex flex-wrap gap-1.5 max-h-32 overflow-y-auto pr-1">
              {ALL_SKILLS.map(s=>(
                <span key={s} onClick={()=>toggleSkill(s)}
                  className={`cursor-pointer text-xs px-2.5 py-1 rounded-full border-2 font-medium transition-all select-none ${
                    form.skills.includes(s)?"bg-blue-600 border-blue-600 text-white":"bg-white border-slate-200 text-slate-500 hover:border-blue-300 hover:text-blue-600"
                  }`}>{s}
                </span>
              ))}
            </div>
          </div>

          <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-xl">
            <input type="checkbox" id="isActive" checked={form.isActive} onChange={e=>upd("isActive",e.target.checked)}
              className="w-4 h-4 accent-blue-600 cursor-pointer"/>
            <label htmlFor="isActive" className="text-sm font-medium text-slate-700 cursor-pointer">Publish immediately</label>
          </div>

          <div className="flex gap-3 pt-1">
            <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50 transition-colors">Cancel</button>
            <button
              onClick={()=>valid&&onSave(form)}
              disabled={!valid}
              className={`flex-1 text-white text-sm font-semibold py-2.5 rounded-xl transition-all ${valid?"shimmer-btn":"bg-slate-200 text-slate-400 cursor-not-allowed"}`}
            >
              {isEdit?"Save changes →":"Post offer →"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

function DeleteModal({ offer, onClose, onConfirm }) {
  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-box max-w-sm text-center" onClick={e=>e.stopPropagation()}>
        <div className="text-4xl mb-3">🗑️</div>
        <h3 className="font-syne font-bold text-slate-900 text-lg mb-2">Delete this offer?</h3>
        <p className="text-sm text-slate-500 font-light mb-6">
          <strong className="text-slate-700">"{offer.title}"</strong> will be permanently removed.
        </p>
        <div className="flex gap-3">
          <button onClick={onClose} className="flex-1 py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50 transition-colors">Cancel</button>
          <button onClick={onConfirm} className="flex-1 danger-btn text-white text-sm font-semibold py-2.5 rounded-xl">Yes, delete</button>
        </div>
      </div>
    </div>
  );
}

export default function CompanyOffers() {
  const [offers,  setOffers]  = useState(INIT_OFFERS);
  const [modal,   setModal]   = useState(null); 
  const [delModal,setDelModal]= useState(null);
  const [filter,  setFilter]  = useState("all");

  const filtered = offers.filter(o =>
    filter==="all" ? true : filter==="active" ? o.isActive : !o.isActive
  );
  const handleSave = (form) => {
    if (form.id) {
      setOffers(prev => prev.map(o => o.id===form.id ? {...form} : o));
    } else {
      setOffers(prev => [{...form, id:Date.now(), applicants:0, posted:new Date().toLocaleDateString("en-US",{month:"short",day:"numeric"})}, ...prev]);
    }
    setModal(null);
  };

  const handleDelete = () => {
    setOffers(prev => prev.filter(o => o.id !== delModal.id));
    setDelModal(null);
  };

  const toggleActive = (id) => setOffers(prev => prev.map(o => o.id===id ? {...o, isActive:!o.isActive} : o));

  return (
    <CompanyLayout active="offers">
      <div className="p-5 md:p-8 max-w-4xl mx-auto">

        {/* Header */}
        <div className="anim-fade-up flex items-start justify-between flex-wrap gap-3 mb-6">
          <div>
            <p className="text-xs font-semibold text-blue-500 uppercase tracking-widest mb-1">Offers</p>
            <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Manage offers</h1>
            <p className="text-slate-400 text-sm font-light mt-0.5">
              {offers.filter(o=>o.isActive).length} active · {offers.filter(o=>!o.isActive).length} closed
            </p>
          </div>
          <button onClick={()=>setModal("create")} className="shimmer-btn text-white text-sm font-semibold px-5 py-2.5 rounded-xl shrink-0">
            + Post new offer
          </button>
        </div>

        {/* Filter tabs */}
        <div className="anim-fade-up anim-d1 flex gap-1 bg-slate-100 rounded-xl p-1 w-fit mb-5">
          {[["all","All"],["active","Active"],["closed","Closed"]].map(([v,l])=>(
            <button key={v} onClick={()=>setFilter(v)} className={`tab-btn ${filter===v?"active":"inactive"}`}>{l}</button>
          ))}
        </div>

        {/* Offers list */}
        <div className="anim-fade-up anim-d2 space-y-4">
          {filtered.length > 0 ? filtered.map(offer => (
            <div key={offer.id} className="card border border-slate-200 card-hover p-5">
              <div className="flex items-start justify-between gap-3 mb-3">
                <div className="flex-1">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <h3 className="font-syne font-bold text-slate-800 text-base">{offer.title}</h3>
                    <span className={`badge ${offer.isActive?"badge-green":"badge-slate"}`}>
                      {offer.isActive?"● Active":"● Closed"}
                    </span>
                  </div>
                  <p className="text-xs text-slate-400">{offer.wilaya} · Posted {offer.posted}</p>
                </div>
                <div className="flex gap-2 shrink-0">
                  <button onClick={()=>toggleActive(offer.id)}
                    className={`text-xs font-semibold px-3 py-1.5 rounded-lg border transition-colors ${
                      offer.isActive
                        ?"border-slate-200 text-slate-600 hover:bg-red-50 hover:text-red-600 hover:border-red-200"
                        :"border-emerald-200 text-emerald-600 bg-emerald-50 hover:bg-emerald-100"
                    }`}>
                    {offer.isActive ? "Close" : "Reopen"}
                  </button>
                  <button onClick={()=>setModal(offer)}
                    className="text-xs font-semibold px-3 py-1.5 rounded-lg border border-slate-200 text-slate-600 hover:bg-blue-50 hover:text-blue-600 hover:border-blue-200 transition-colors">
                    Edit
                  </button>
                  <button onClick={()=>setDelModal(offer)}
                    className="text-xs font-semibold px-3 py-1.5 rounded-lg border border-slate-200 text-slate-400 hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-colors">
                    🗑
                  </button>
                </div>
              </div>

              <p className="text-sm text-slate-500 font-light leading-relaxed mb-3 line-clamp-2">{offer.description}</p>
              <div className="flex flex-wrap gap-1.5 mb-3">
                <span className={`badge ${TYPE_BADGE[offer.internshipType]}`}>{offer.internshipType}</span>
                <span className="badge badge-slate">{offer.domain}</span>
                <span className="badge badge-slate">⏱ {offer.duration}</span>
              </div>

              <div className="flex flex-wrap gap-1.5 mb-3">
                {offer.skills.map(s=><span key={s} className="skill-chip">{s}</span>)}
              </div>

              <div className="flex items-center justify-between pt-3 border-t border-slate-100">
                <span className="text-xs text-slate-400">👥 {offer.applicants} applicant{offer.applicants!==1?"s":""}</span>
                <div className="w-32 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                  <div className="progress-bar-inner" style={{width:`${Math.min(offer.applicants*5,100)}%`}}/>
                </div>
              </div>
            </div>
          )) : (
            <div className="text-center py-16">
              <div className="text-5xl mb-3">📋</div>
              <h3 className="font-syne font-bold text-slate-700 text-lg mb-1">No {filter} offers</h3>
              <p className="text-sm text-slate-400 mb-4">Post your first internship offer to start receiving applications.</p>
            </div>
          )}
        </div>
      </div>

      {modal && (
        <OfferModal
          offer={modal==="create" ? null : modal}
          onClose={()=>setModal(null)}
          onSave={handleSave}
        />
      )}
      {delModal && (
        <DeleteModal offer={delModal} onClose={()=>setDelModal(null)} onConfirm={handleDelete}/>
      )}
    </CompanyLayout>
  );
}
